```js
if (first && first.below > lo) { const n = Math.ceil(20 * Math.log10(first.below / lo)); let prev = lo;
  for (let i = 1; i <= n; i++) { const u = lo * Math.pow(first.below / lo, i / n);
    if (HAZARDS.some((h) => h.test(M, at(u), opt))) { let a = prev, b = u; while (b / a > 1 + R.TOL) { const m = Math.sqrt(a * b); if (HAZARDS.some((h) => h.test(M, at(m), opt))) b = m; else a = m; }
      first = { use: b, below: a, by: HAZARDS.find((h) => h.test(M, at(b), opt)).id }; break; }
    prev = u; } }
```
