if (e === 'least') {
  const gl = p.goal(); out.goal = gl;
  const want = gl.reached ? gl.use : undefined;            // undefined = all-out
  const ce = p.ceiling(); out.ceiling = ce;
  const goalText = GOALS[move].text(goalTarget(move)).replace(/^(\w+)s /, '$1 ');
  if (!ce.by || (want == null ? c.F : want) <= ce.below) { out.use = want; if (!gl.reached) out.note = 'Even all-out he can’t ' + goalText + '. All-out harms nothing here.'; return out; }
  out.use = ce.below > 0 ? ce.below : p.lo;
  out.note = (gl.reached ? 'To ' + goalText + ' he would need more, and past this ' : 'Even all-out he can’t ' + goalText + ', and past this ') + EFF_HAZ[ce.by].what + '. Showing the most he can do with nothing harmed.';
